import{_ as a,a0 as p,w as e,s as d,I as i,x as o,a1 as n,A as r,ao as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"JStock：Linux 上不錯的股票投資組合管理軟件 | LCTT x X-CMD","titleTemplate":false,"description":"JStock：Linux 上不錯的股票投資組合管理軟件 | LCTT (201607) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"JStock：Linux 上不錯的股票投資組合管理軟件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"JStock：Linux 上不錯的股票投資組合管理軟件 | LCTT (201607) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201607/20160104 What is good stock portfolio management software on Linux","title":"JStock：Linux 上不錯的股票投資組合管理軟件","tag":"201607","desc":""},"relativePath":"201607/20160104 What is good stock portfolio management software on Linux.md","filePath":"[post].md"}'),k={name:"201607/20160104 What is good stock portfolio management software on Linux.md"};function m(u,t,f,g,x,S){const l=p("Link");return e(),d("div",null,[t[27]||(t[27]=i("h1",{id:"jstock-linux-上不錯的股票投資組合管理軟件",tabindex:"-1"},[o("JStock：Linux 上不錯的股票投資組合管理軟件 "),i("a",{class:"header-anchor",href:"#jstock-linux-上不錯的股票投資組合管理軟件","aria-label":"Permalink to “JStock：Linux 上不錯的股票投資組合管理軟件”"},"​")],-1)),t[28]||(t[28]=i("p",null,"如果你在股票市場做投資，那麼你可能非常清楚投資組合管理計劃有多重要。管理投資組合的目標是依據你能承受的風險，時間層面的長短和資金盈利的目標去為你量身打造的一種投資計劃。鑑於這類軟件的重要性，因此從來不會缺乏商業性的 app 和股票行情檢測軟件，每一個都可以兜售複雜的投資組合以及跟蹤報告功能。",-1)),i("p",null,[t[1]||(t[1]=o("對於我們這些 Linux 愛好者們，我也找到了一些",-1)),t[2]||(t[2]=i("strong",null,"好用的開源投資組合管理工具",-1)),t[3]||(t[3]=o("，用來在 Linux 上管理和跟蹤股票的投資組合，這裏高度推薦一個基於 java 編寫的管理軟件 ",-1)),n(l,{href:"http://jstock.org/"},{default:r(()=>[...t[0]||(t[0]=[o("JStock",-1)])]),_:1}),t[4]||(t[4]=o("。如果你不是一個 java 粉，也許你會放棄它，JStock 需要運行在沉重的 JVM 環境上。但同時，在每一個安裝了 JRE 的環境中它都可以馬上運行起來，在你的 Linux 環境中它會運行的很順暢。",-1))]),t[29]||(t[29]=i("p",null,"“開源”就意味着免費或標準低下的時代已經過去了。鑑於 JStock 只是一個個人完成的產物，作為一個投資組合管理軟件它最令人印象深刻的是包含了非常多實用的功能，以上所有的榮譽屬於它的作者 Yan Cheng Cheok！例如，JStock 支持通過監視列表去監控價格，多種投資組合，自選/內置的股票指標與相關監測，支持27個不同的股票市場和跨平台的雲端備份/還原。JStock 支持多平台部署（Linux, OS X, Android 和 Windows），你可以通過雲端保存你的 JStock 投資組合，並通過雲平台無縫的備份/還原到其他的不同平台上面。",-1)),t[30]||(t[30]=i("p",null,"現在我將向你展示如何安裝以及使用過程的一些具體細節。",-1)),t[31]||(t[31]=i("h3",{id:"在-linux-上安裝-jstock",tabindex:"-1"},[o("在 Linux 上安裝 JStock "),i("a",{class:"header-anchor",href:"#在-linux-上安裝-jstock","aria-label":"Permalink to “在 Linux 上安裝 JStock”"},"​")],-1)),i("p",null,[t[6]||(t[6]=o("因為 JStock 使用Java編寫，所以必須",-1)),n(l,{href:"http://ask.xmodulo.com/install-java-runtime-Linux.html"},{default:r(()=>[...t[5]||(t[5]=[o("安裝 JRE",-1)])]),_:1}),t[7]||(t[7]=o("才能讓它運行起來。小提示，JStock 需要 JRE1.7 或更高版本。如你的 JRE 版本不能滿足這個需求，JStock 將會運行失敗然後出現下面的報錯。",-1))]),t[32]||(t[32]=s(`<pre><code>Exception in thread &quot;main&quot; java.lang.UnsupportedClassVersionError: org/yccheok/jstock/gui/JStock : Unsupported major.minor version 51.0
</code></pre><p>在你的 Linux 上安裝好了 JRE 之後，從其官網下載最新的發佈的 JStock，然後加載啓動它。</p><pre><code>$ wget https://github.com/yccheok/jstock/releases/download/release_1-0-7-13/jstock-1.0.7.13-bin.zip
$ unzip jstock-1.0.7.13-bin.zip
$ cd jstock
$ chmod +x jstock.sh
$ ./jstock.sh
</code></pre><p>教程的其他部分，讓我來給大家展示一些 JStock 的實用功能</p><h3 id="監視監控列表中股票價格的波動" tabindex="-1">監視監控列表中股票價格的波動 <a class="header-anchor" href="#監視監控列表中股票價格的波動" aria-label="Permalink to “監視監控列表中股票價格的波動”">​</a></h3><p>使用 JStock 你可以創建一個或多個監視列表，它可以自動的監視股票價格的波動並給你提供相應的通知。在每一個監視列表裏面你可以添加多個感興趣的股票進去。之後在“Fall Below”和“Rise Above”的表格裏添加你的警戒值，分別設定該股票的最低價格和最高價格。</p><p><img src="https://c2.staticflickr.com/2/1588/23795349969_37f4b0f23c_c.jpg" alt=""></p><p>例如你設置了 AAPL 股票的最低/最高價格分別是 $102 和 $115.50，只要在價格低於 $102 或高於 $115.50 時你就得到桌面通知。</p><p>你也可以設置郵件通知，這樣你將收到一些價格信息的郵件通知。設置郵件通知在“Options”菜單裏，在“Alert”標籤中國，打開“Send message to email(s)”，填入你的 Gmail 賬户。一旦完成 Gmail 認證步驟，JStock 就會開始發送郵件通知到你的 Gmail 賬户（也可以設置其他的第三方郵件地址）。</p><p><img src="https://c2.staticflickr.com/2/1644/24080560491_3aef056e8d_b.jpg" alt=""></p><h3 id="管理多個投資組合" tabindex="-1">管理多個投資組合 <a class="header-anchor" href="#管理多個投資組合" aria-label="Permalink to “管理多個投資組合”">​</a></h3><p>JStock 允許你管理多個投資組合。這個功能對於你使用多個股票經紀人時是非常實用的。你可以為每個經紀人創建一個投資組合去管理你的“買入/賣出/紅利”用來了解每一個經紀人的業務情況。你也可以在“Portfolio”菜單裏面選擇特定的投資組合來切換不同的組合項目。下面是一張截圖用來展示一個假設的投資組合。</p><p><img src="https://c2.staticflickr.com/2/1646/23536385433_df6c036c9a_c.jpg" alt=""></p><p>你也可以設置付給中介費，你可以為每個買賣交易設置中介費、印花税以及結算費。如果你比較懶，你也可以在選項菜單裏面啓用自動費用計算，並提前為每一家經濟事務所設置費用方案。當你為你的投資組合增加交易之後，JStock 將自動的計算並計入費用。</p><p><img src="https://c2.staticflickr.com/2/1653/24055085262_0e315c3691_b.jpg" alt=""></p><h3 id="使用內置-自選股票指標來監控" tabindex="-1">使用內置/自選股票指標來監控 <a class="header-anchor" href="#使用內置-自選股票指標來監控" aria-label="Permalink to “使用內置/自選股票指標來監控”">​</a></h3>`,16)),i("p",null,[t[9]||(t[9]=o("如果你要做一些股票的技術分析，你可能需要基於各種不同的標準來監控股票（這裏叫做“股票指標”）。對於股票的跟蹤，JStock提供多個",-1)),n(l,{href:"http://jstock.org/ma_indicator.html"},{default:r(()=>[...t[8]||(t[8]=[o("預設的技術指示器",-1)])]),_:1}),t[10]||(t[10]=o(" 去獲得股票上漲/下跌/逆轉指數的趨勢。下面的列表裏面是一些可用的指標。",-1))]),t[33]||(t[33]=s('<ul><li>平滑異同移動平均線（MACD）</li><li>相對強弱指標 (RSI)</li><li>資金流向指標 (MFI)</li><li>順勢指標 (CCI)</li><li>十字線</li><li>黃金交叉線，死亡交叉線</li><li>漲幅/跌幅</li></ul><p>開啓預設指示器能需要在 JStock 中點擊“Stock Indicator Editor”標籤。之後點擊右側面板中的安裝按鈕。選擇“Install from JStock server”選項，之後安裝你想要的指示器。</p><p><img src="https://c2.staticflickr.com/2/1476/23867534660_b6a9c95a06_c.jpg" alt=""></p><p>一旦安裝了一個或多個指示器，你可以用他們來掃描股票。選擇“Stock Indicator Scanner”標籤，點擊底部的“Scan”按鈕，選擇需要的指示器。</p><p><img src="https://c2.staticflickr.com/2/1653/24137054996_e8fcd10393_c.jpg" alt=""></p><p>當你選擇完需要掃描的股票（例如， NYSE, NASDAQ）以後，JStock 將執行該掃描，並將該指示器捕獲的結果通過列表展現。</p><p><img src="https://c2.staticflickr.com/2/1446/23795349889_0f1aeef608_c.jpg" alt=""></p><p>除了預設指示器以外，你也可以使用一個圖形化的工具來定義自己的指示器。下面這張圖例用於監控當前價格小於或等於60天平均價格的股票。</p><p><img src="https://c2.staticflickr.com/2/1605/24080560431_3d26eac6b5_c.jpg" alt=""></p><h3 id="通過雲在-linux-和-android-jstock-之間備份-恢復" tabindex="-1">通過雲在 Linux 和 Android JStock 之間備份/恢復### <a class="header-anchor" href="#通過雲在-linux-和-android-jstock-之間備份-恢復" aria-label="Permalink to “通過雲在 Linux 和 Android JStock 之間備份/恢復###”">​</a></h3><p>另一個非常棒的功能是 JStock 支持雲備份恢復。Jstock 可以通過 Google Drive 把你的投資組合/監視列表在雲上備份和恢復，這個功能可以實現在不同平台上無縫穿梭。如果你在兩個不同的平台之間來回切換使用 Jstock，這種跨平台備份和還原非常有用。我在 Linux 桌面和 Android 手機上測試過我的 Jstock 投資組合，工作的非常漂亮。我在 Android 上將 Jstock 投資組合信息保存到 Google Drive 上，然後我可以在我的 Linux 版的 Jstock 上恢復它。如果能夠自動同步到雲上，而不用我手動地觸發雲備份/恢復就更好了，十分期望這個功能出現。</p><p><img src="https://c2.staticflickr.com/2/1537/24163165565_bb47e04d6c_c.jpg" alt=""></p><p><img src="https://c2.staticflickr.com/2/1556/23536385333_9ed1a75d72_c.jpg" alt=""></p><p>如果你在從 Google Drive 還原之後不能看到你的投資信息以及監視列表，請確認你的國家信息與“Country”菜單裏面設置的保持一致。</p>',14)),i("p",null,[t[12]||(t[12]=o("JStock 的安卓免費版可以從 ",-1)),n(l,{href:"https://play.google.com/store/apps/details?id=org.yccheok.jstock.gui"},{default:r(()=>[...t[11]||(t[11]=[o("Google Play Store",-1)])]),_:1}),t[13]||(t[13]=o(" 獲取到。如果你需要完整的功能（比如雲備份，通知，圖表等），你需要一次性支付費用升級到高級版。我認為高級版物有所值。",-1))]),t[34]||(t[34]=i("p",null,[i("img",{src:"https://c2.staticflickr.com/2/1687/23867534720_18b917028c_c.jpg",alt:""})],-1)),t[35]||(t[35]=i("p",null,"寫在最後，我應該説一下它的作者，Yan Cheng Cheok，他是一個十分活躍的開發者，有bug及時反饋給他。這一切都要感謝他！！！",-1)),t[36]||(t[36]=i("p",null,"關於 JStock 這個投資組合跟蹤軟件你有什麼想法呢？",-1)),t[37]||(t[37]=i("hr",null,null,-1)),i("p",null,[t[15]||(t[15]=o("via: ",-1)),n(l,{href:"http://xmodulo.com/stock-portfolio-management-software-Linux.html"},{default:r(()=>[...t[14]||(t[14]=[o("http://xmodulo.com/stock-portfolio-management-software-Linux.html",-1)])]),_:1})]),i("p",null,[t[19]||(t[19]=o("作者：",-1)),n(l,{href:"http://xmodulo.com/author/nanni"},{default:r(()=>[...t[16]||(t[16]=[o("Dan Nanni",-1)])]),_:1}),t[20]||(t[20]=o(" 譯者：",-1)),n(l,{href:"https://github.com/ivo-wang"},{default:r(()=>[...t[17]||(t[17]=[o("ivo-wang",-1)])]),_:1}),t[21]||(t[21]=o(" 校對：",-1)),n(l,{href:"https://github.com/wxy"},{default:r(()=>[...t[18]||(t[18]=[o("wxy",-1)])]),_:1})]),i("p",null,[t[24]||(t[24]=o("本文由 ",-1)),n(l,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[22]||(t[22]=[o("LCTT",-1)])]),_:1}),t[25]||(t[25]=o(" 原創編譯，",-1)),n(l,{href:"https://Linux.cn/"},{default:r(()=>[...t[23]||(t[23]=[o("Linux中國",-1)])]),_:1}),t[26]||(t[26]=o(" 榮譽推出",-1))])])}const j=a(k,[["render",m]]);export{L as __pageData,j as default};
